  const byId = (id) => document.getElementById(id);

  function render(key) {
    const offer = offers[key];
    byId("offer-title").textContent = offer.title;
    byId("offer-description").textContent = offer.lead;
    byId("offer-example").textContent = offer.example;
    const scope = offer.scope.map((step) => {
      const row = document.createElement("li");
      row.textContent = step;
      return row;
    });
    byId("offer-scope").replaceChildren(...scope);
    const link = byId("offer-demo");
    link.firstElementChild.textContent = offer.link;
    const params = new URLSearchParams({ ...offer.route, offer: key });
    if (new URLSearchParams(location.search).get("via") === "telegram") params.set("via", "telegram");
    link.href = `?${params}`;
  }

  return {
    has: (key) => Object.hasOwn(offers, key),
    title: (key) => offers[key].title,
    render,
  };
